+func TestInitialStateDoesNotReplaceExistingState(t *testing.T) {
+	dir := t.TempDir()
+	probe := filepath.Join(dir, "probe")
+	require.NoError(t, os.WriteFile(probe, nil, 0600))
+	if err := os.Link(probe, probe+"-link"); err != nil {
+		t.Skipf("filesystem does not support hard links: %v", err)
+	}
+	reporter, err := NewReporter(testConfig(dir), logrus.New())
+	require.NoError(t, err)
+	want := readState(t, dir)
+	reporter.state.UUID = uuid.Must(uuid.NewV4()).String()
+
+	require.True(t, os.IsExist(reporter.writeState(true)))
+	require.Equal(t, want, readState(t, dir))
+}
